/**
 * Replaces all segments in this writer's {@link SegmentInfos} with those from {@code commit}, but
 * keeps generation, version and counter so that future commits remain write once.
 */
void replace(IndexCommit commit, Directory expectedDirectory, InfoStream stream)
    throws IOException {
  SegmentInfos current = this.segmentInfos;
  Directory commitDirectory = commit.getDirectory();
  if (commitDirectory != expectedDirectory) {
    throw new IllegalArgumentException(
        "IndexCommit's directory doesn't match my directory, expected="
            + expectedDirectory
            + ", got="
            + commitDirectory);
  }

  String commitSegmentsFile = commit.getSegmentsFileName();
  SegmentInfos other = SegmentInfos.readCommit(expectedDirectory, commitSegmentsFile);
  StringBuilder loaded =
      new StringBuilder("init: loaded commit \"").append(commitSegmentsFile).append('"');

  current.clear();
  int createdMajor = current.getIndexCreatedVersionMajor();
  for (SegmentCommitInfo commitInfo : other.asList()) {
    SegmentInfo info = commitInfo.info;
    Version minVersion = info.minVersion;
    if (createdMajor >= 7 && minVersion == null) {
      throw new IllegalArgumentException(
          "All segments must record the minVersion for indices created on or after Lucene 7");
    }
    int maxDoc = info.maxDoc();
    int delCount = commitInfo.getDelCount();
    if (delCount < 0 || delCount > maxDoc) {
      throw new IllegalStateException(
          "cannot replace segment: invalid maxDoc=" + maxDoc + " delCount=" + delCount);
    }
    Codec codec = info.getCodec();
    Version version = info.getVersion();
    loaded
        .append(" codec=")
        .append(codec.getName())
        .append(" major=")
        .append(version.major)
        .append(" maxDoc=")
        .append(maxDoc)
        .append(" dels=")
        .append(delCount);
    current.add(commitInfo);
  }
  current.lastGeneration = other.lastGeneration;

  if (stream.isEnabled("IW")) {
    stream.message("IW", loaded.toString());
  }
}

/** Confirms that the incoming index sort (if any) matches the existing index sort (if any). */
private void validateIndexSort() {
  Sort indexSort = config.getIndexSort();
  if (indexSort != null) {
    for (SegmentCommitInfo info : segmentInfos) {
      Sort segmentIndexSort = info.info.getIndexSort();
      if (segmentIndexSort == null || isCongruentSort(indexSort, segmentIndexSort) == false) {
        throw new IllegalArgumentException(
            "cannot change previous indexSort="
                + segmentIndexSort
                + " (from segment="
                + info
                + ") to new indexSort="
                + indexSort);
      }
    }
  }
}

/** Returns true if <code>indexSort</code> is a prefix of <code>otherSort</code>. */
static boolean isCongruentSort(Sort indexSort, Sort otherSort) {
  final SortField[] fields1 = indexSort.getSort();
  final SortField[] fields2 = otherSort.getSort();
  if (fields1.length > fields2.length) {
    return false;
  }
  return Arrays.asList(fields1).equals(Arrays.asList(fields2).subList(0, fields1.length));
}

// reads latest field infos for the commit
// this is used on IW init and addIndexes(Dir) to create/update the global field map.
// TODO: fix tests abusing this method!
static FieldInfos readFieldInfos(SegmentCommitInfo si) throws IOException {
  Codec codec = si.info.getCodec();
  FieldInfosFormat reader = codec.fieldInfosFormat();

  if (si.hasFieldUpdates()) {
    // there are updates, we read latest (always outside of CFS)
    final String segmentSuffix = Long.toString(si.getFieldInfosGen(), Character.MAX_RADIX);
    return reader.read(si.info.dir, si.info, segmentSuffix, IOContext.READONCE);
  } else if (si.info.getUseCompoundFile()) {
    // cfs
    try (Directory cfs =
        codec.compoundFormat().getCompoundReader(si.info.dir, si.info, IOContext.DEFAULT)) {
      return reader.read(cfs, si.info, "", IOContext.READONCE);
    }
  } else {
    // no cfs
    return reader.read(si.info.dir, si.info, "", IOContext.READONCE);
  }
}

/**
 * Loads or returns the already loaded the global field number map for this {@link SegmentInfos}.
 * If this {@link SegmentInfos} has no global field number map the returned instance is empty
 */
private FieldNumbers getFieldNumberMap() throws IOException {
  final FieldNumbers map = new FieldNumbers(config.softDeletesField);

  for (SegmentCommitInfo info : segmentInfos) {
    FieldInfos fis = readFieldInfos(info);
    for (FieldInfo fi : fis) {
      map.addOrGet(fi);
    }
  }

